use xiom.io;

fn main() {
  let score = 72;

  if score >= 50 {
    io.println("You passed! Great job!");
  } else {
    io.println("Keep trying — you'll get it!");
  }

  let number = -3;
  if number >= 0 {
    io.println("Positive!");
  } else {
    io.println("Negative!");
  }
}
